  "brief": {
    "title": "Lichess Chess Game Analytics: Patterns of Victory, Openings, and Player Dynamics",
    "one_liner": "A comprehensive analysis of over 20,000 Lichess chess games exploring win rates, opening strategies, rating dynamics, and game outcome patterns.",
    "goal": "The reader should gain a thorough understanding of the key factors that influence game outcomes on Lichess, including the impact of color (white vs. black), rating differentials, opening choices, and time controls — enabling data-driven insights for chess enthusiasts, coaches, and platform analysts."
  },
  "required_sections": [
    {
      "section_id": "overview",
      "title": "Dataset Overview & Game Distribution",
      "objective": "Summarize the dataset scope, including total games, proportion of rated vs. unrated games, distribution of game outcomes (mate, resign, outoftime, draw), and winner distribution (white, black, draw)."
    },
    {
      "section_id": "color-advantage",
      "title": "White vs. Black: The First-Move Advantage",
      "objective": "Analyze win rates by color across all games and by victory status. Quantify whether white holds a statistically meaningful advantage and how this varies by rating bracket and time control."
    },
    {
      "section_id": "rating-analysis",
      "title": "Rating Dynamics and Their Impact on Outcomes",
      "objective": "Examine the distribution of player ratings, the relationship between rating differentials and win probability, and how average game length (turns) varies across rating tiers."
    },
    {
      "section_id": "opening-strategy",
      "title": "Opening Analysis: Popular Openings and Their Success Rates",
      "objective": "Identify the most frequently played openings (by ECO code and name), their win rates for white and black, and the relationship between opening depth (opening_ply) and game outcomes."
    },
    {
      "section_id": "time-control",
      "title": "Time Control Patterns and Game Characteristics",
      "objective": "Analyze how different time increments (increment_code) affect game length, victory status distribution, and the likelihood of timeout vs. checkmate vs. resignation."
    },
    {
      "section_id": "key-findings",
      "title": "Key Findings and Strategic Takeaways",
      "objective": "Synthesize the most important patterns discovered across all analyses into actionable insights for players and chess analysts."
    }
  ],
  "kpis": [
    {
      "name": "White Win Rate",
      "description": "Percentage of games won by white out of all decisive games (excluding draws)."
    },
    {
      "name": "Average Game Length",
      "description": "Mean number of turns per game, segmented by victory status and rating tier."
    },
    {
      "name": "Checkmate Rate",
      "description": "Percentage of games that end in checkmate (mate) versus resignation or timeout."
    },
    {
      "name": "Rating Differential Impact",
      "description": "Correlation between the absolute rating difference (white_rating - black_rating) and the probability of the higher-rated player winning."
    },
    {
      "name": "Top Opening Win Rate",
      "description": "Win rate of the top 10 most popular openings for both white and black."
    }
  ],
  "analysis_dimensions": [
    "winner",
    "victory_status",
    "opening_eco",
    "increment_code",
    "white_rating"
  ]
}

